'use strict';

// Full guest/API regression. The EXE creates two real Windows threads, joins
// them, and asserts DLL notifications itself. run.js chooses the production
// cooperative scheduler or Node guest-worker; no loader/export mocks.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const cp = require('node:child_process');
const crypto = require('node:crypto');
const ROOT = path.join(__dirname, '..');
const OUT = process.env.WA_DLL_LIFECYCLE_ARTIFACTS || path.join(ROOT, 'scratch/dll-lifecycle-real-pe-v2');
const BASE = 0x400000, DATA = BASE + 0x1400;
const API = ['LoadLibraryA', 'FreeLibrary', 'FreeLibraryAndExitThread', 'CreateThread',
  'WaitForSingleObject', 'GetExitCodeThread', 'GetModuleHandleA', 'Sleep', 'ExitThread', 'ExitProcess',
  'TlsAlloc', 'TlsGetValue', 'TlsSetValue', 'TlsFree', 'GetProcAddress', 'GetModuleFileNameA', 'VirtualQuery', 'EnumResourceTypesA'];
const iat = name => 0x1900 + API.indexOf(name) * 4;
const u32 = n => [n & 255, (n >>> 8) & 255, (n >>> 16) & 255, n >>> 24];
class X86 {
  constructor() { this.code = []; this.labels = new Map(); this.fixups = []; this.failures = []; }
  emit(...bytes) { this.code.push(...bytes.flat()); return this; }
  label(name) { this.labels.set(name, this.code.length); return this; }
  branch(op, target) { this.emit(op); this.fixups.push([this.code.length, target]); return this.emit(0, 0, 0, 0); }
  push(n) { return this.emit(0x68, u32(n)); }
  api(name, dll = false) { return dll ? this.emit(0xff, 0x93, u32(iat(name))) : this.emit(0xff, 0x15, u32(BASE + iat(name))); }
  store(offset, value) { return this.emit(0xc7, 0x05, u32(DATA + offset), u32(value)); }
  eaxTo(offset) { return this.emit(0xa3, u32(DATA + offset)); }
  eaxFrom(offset) { return this.emit(0xa1, u32(DATA + offset)); }
  checkEax(value) {
    const id = this.failures.length + 101, label = `failure-${id}`;
    this.emit(0x3d, u32(value)).branch([0x0f, 0x85], label); this.failures.push([label, id]); return this;
  }
  checkMem(offset, value) { return this.eaxFrom(offset).checkEax(value); }
  finish() {
    for (const [label, id] of this.failures) this.label(label).push(id).api('ExitProcess').emit(0xcc);
    const bytes = Buffer.from(this.code);
    for (const [at, target] of this.fixups) {
      assert(this.labels.has(target), `missing x86 label ${target}`);
      bytes.writeInt32LE(this.labels.get(target) - at - 4, at);
    }
    return bytes;
  }
}

function pe(parts, dll = false) {
  const b = Buffer.alloc(0x2200), p = 0x80, o = p + 24, s = o + 0xe0;
  b.writeUInt16LE(0x5a4d, 0); b.writeUInt32LE(p, 0x3c);
  b.writeUInt32LE(0x4550, p); b.writeUInt16LE(0x14c, p + 4);
  b.writeUInt16LE(1, p + 6); b.writeUInt16LE(0xe0, p + 20);
  b.writeUInt16LE(dll ? 0x210e : 0x010e, p + 22);
  b.writeUInt16LE(0x10b, o); b.writeUInt32LE(dll ? 0x1000 : 0x2000, o + 16);
  b.writeUInt32LE(dll ? 0x10000000 : BASE, o + 28);
  b.writeUInt32LE(0x1000, o + 32); b.writeUInt32LE(0x200, o + 36);
  b.writeUInt32LE(0x3000, o + 56); b.writeUInt32LE(0x200, o + 60);
  b.writeUInt16LE(3, o + 68); b.writeUInt32LE(0x100000, o + 72);
  b.writeUInt32LE(0x1000, o + 76); b.writeUInt32LE(16, o + 92);
  b.write('.text', s); b.writeUInt32LE(0x2000, s + 8);
  b.writeUInt32LE(0x1000, s + 12); b.writeUInt32LE(0x2000, s + 16);
  b.writeUInt32LE(0x200, s + 20); b.writeUInt32LE(0xe0000060, s + 36);
  const raw = rva => rva - 0x1000 + 0x200;
  b.writeUInt32LE(0x1800, o + 104); b.writeUInt32LE(40, o + 108);
  b.writeUInt32LE(0x1900, raw(0x1800)); b.writeUInt32LE(0x1880, raw(0x180c));
  b.writeUInt32LE(0x1900, raw(0x1810)); b.write('kernel32.dll\0', raw(0x1880));
  let cursor = 0x1a00;
  for (const name of API) {
    b.writeUInt32LE(cursor, raw(iat(name))); b.write(name + '\0', raw(cursor + 2));
    cursor += name.length + 3;
  }
  for (const [rva, data] of parts) Buffer.from(data).copy(b, raw(rva));
  return b;
}

function dll(kind) {
  const offset = { self: 0, nested: 0x20, bad: 0x40, other: 0x90, tls: 0xc0, resource: 0xb4 }[kind];
  const a = new X86();
  // Preserve EBX. Callback args move by one word after that push.
  a.emit(0x53, 0x8b, 0x5c, 0x24, 8, 0x8b, 0x44, 0x24, 12);
  a.emit(0xff, 0x04, 0x85, u32(DATA + offset)); // ++counters[reason]
  if (kind === 'self' || kind === 'bad') {
    a.emit(0x83, 0xf8, 1).branch([0x0f, 0x84], 'attach');
    a.emit(0x85, 0xc0).branch([0x0f, 0x85], 'ok');
    a.emit(0xff, 0xb3, u32(0x1700)).api('FreeLibrary', true).branch(0xe9, 'ok');
    a.label('attach').emit(0x8d, 0x83, u32(0x1500), 0x50).api('LoadLibraryA', true);
    a.emit(0x89, 0x83, u32(0x1700));
    if (kind === 'bad') a.emit(0x31, 0xc0, 0x5b, 0xc2, 12, 0);
  }
  a.label('ok').emit(0xb8, 1, 0, 0, 0, 0x5b, 0xc2, 12, 0);
  const thread = new X86();
  thread.emit(0x8b, 0x5c, 0x24, 4).push(73).emit(0x53).api('FreeLibraryAndExitThread', true);
  thread.store(0x60, 1).emit(0xcc); // must never execute, including final self-unload
  const image = pe([[0x1000, a.finish()], [0x1200, thread.finish()],
    [0x1250, [0xb8, kind === 'other' ? 19 : 7, 0, 0, 0, 0xc3]],
    [0x1500, 'nested.dll\0']], true);
  if (kind === 'tls') {
    const o = 0x80 + 24, raw = rva => rva - 0x1000 + 0x200;
    image.writeUInt32LE(0x1600, o + 168); image.writeUInt32LE(24, o + 172);
    image.writeUInt32LE(0x10001620, raw(0x1600)); image.writeUInt32LE(0x10001624, raw(0x1604));
    image.writeUInt32LE(0x10001630, raw(0x1608)); image.writeUInt32LE(0x11223344, raw(0x1620));
    image.writeUInt32LE(0x1d00, o + 136); image.writeUInt32LE(16, o + 140);
    image.writeUInt32LE(0x1000, raw(0x1d00)); image.writeUInt32LE(16, raw(0x1d04));
    [0x3600, 0x3604, 0x3608, 0].forEach((x, i) => image.writeUInt16LE(x, raw(0x1d08) + i * 2));
  }
  if (kind === 'resource') {
    const o = 0x80 + 24, raw = rva => rva - 0x1000 + 0x200;
    image.writeUInt32LE(0x1e00, o + 112); image.writeUInt32LE(64, o + 116);
    image.writeUInt16LE(2, raw(0x1e0e));
    image.writeUInt32LE(10, raw(0x1e10)); image.writeUInt32LE(0x80000020, raw(0x1e14));
    image.writeUInt32LE(11, raw(0x1e18)); image.writeUInt32LE(0x80000020, raw(0x1e1c));
  }
  return image;
}

function program(outstanding) {
  const a = new X86();
  const load = name => a.push(BASE + name).api('LoadLibraryA');
  const checkPresent = () => a.emit(0x85, 0xc0).branch([0x0f, 0x84], 'bad-load');
  load(0x1500); checkPresent(); a.eaxTo(0x4c).eaxTo(0x5c).emit(0x89, 0xc3);
  if (outstanding) { load(0x1500); checkPresent(); }
  // Start the sibling in EXE code, and wait until it has executed Self's
  // exported code on its own decoded-code cache before beginning unload.
  a.push(0).push(0).push(0).push(BASE + 0x2900).push(0).push(0).api('CreateThread');
  checkPresent(); a.eaxTo(0x50);
  a.label('ready').push(1).api('Sleep').eaxFrom(0x70).emit(0x85, 0xc0).branch([0x0f, 0x84], 'ready');
  a.push(0).push(0).emit(0x53, 0x8d, 0x83, u32(0x1200), 0x50).push(0).push(0).api('CreateThread');
  checkPresent(); a.eaxTo(0x54);
  a.push(5000).emit(0x50).api('WaitForSingleObject').checkEax(0);
  a.push(DATA + 0x68).emit(0xff, 0x35, u32(DATA + 0x54)).api('GetExitCodeThread').checkEax(1);
  a.checkMem(0x68, 73).checkMem(0x60, 0);
  a.push(BASE + 0x1500).api('GetModuleHandleA');
  if (outstanding) {
    a.emit(0x39, 0xd8).branch([0x0f, 0x85], 'bad-load');
    a.checkMem(0, 0).checkMem(12, 1); // worker cleanup precedes signaled join
    a.emit(0x53).api('FreeLibrary').checkEax(1);
  } else a.checkEax(0).checkMem(12, 0);
  a.checkMem(0, 1).checkMem(4, 1).checkMem(8, 2).checkMem(0x20, 1);
  // Retired real handles cannot resolve generic API exports or EXE filenames.
  a.push(BASE + 0x15c0).emit(0x53).api('GetProcAddress').checkEax(0);
  a.push(32).push(DATA + 0xe0).emit(0x53).api('GetModuleFileNameA').checkEax(0);
  a.push(28).push(DATA + 0xe0).emit(0x53).api('VirtualQuery').checkEax(28).checkMem(0xf0, 0x10000);
