  // cached this exact entry address from Self; it must now execute Other's 19.
  load(0x1520); checkPresent(); a.eaxTo(0x58);
  a.emit(0x3b, 0x05, u32(DATA + 0x5c)).branch([0x0f, 0x85], 'wrong-reuse');
  a.store(0x74, 1).push(5000).emit(0xff, 0x35, u32(DATA + 0x50)).api('WaitForSingleObject').checkEax(0);
  a.checkMem(0x64, 1).checkMem(0x78, 19);
  a.push(DATA + 0x6c).emit(0xff, 0x35, u32(DATA + 0x50)).api('GetExitCodeThread').checkEax(1);
  a.checkMem(0x6c, 99).checkMem(0x9c, 1);
  a.emit(0xff, 0x35, u32(DATA + 0x58)).api('FreeLibrary').checkEax(1).checkMem(0x90, 1);
  // FALSE attach must invoke its detach (whose own nested FreeLibrary must
  // complete), return NULL, and remove both mappings from subsequent lookup.
  load(0x1540); a.checkEax(0).checkMem(0x44, 1).checkMem(0x40, 1).checkMem(0x20, 2);
  a.push(BASE + 0x1540).api('GetModuleHandleA').checkEax(0);
  a.push(BASE + 0x1560).api('GetModuleHandleA').checkEax(0);
  // Static TLS ownership belongs to the loader even if guest code overwrites
  // its per-thread slot. Unloading returns the index and clears its value.
  load(0x1580); checkPresent(); a.emit(0x89, 0xc3, 0x8b, 0x80, u32(0x1630)).eaxTo(0xa0);
  a.emit(0x50).api('TlsGetValue').emit(0x8b, 0x00).checkEax(0x11223344);
  a.push(0xdeadbeef).emit(0xff, 0x35, u32(DATA + 0xa0)).api('TlsSetValue').checkEax(1);
  a.emit(0x53).api('FreeLibrary').checkEax(1).checkMem(0xc0, 1);
  a.api('TlsAlloc').emit(0x3b, 0x05, u32(DATA + 0xa0)).branch([0x0f, 0x85], 'bad-load');
  a.emit(0x50).api('TlsGetValue').checkEax(0);
  a.emit(0xff, 0x35, u32(DATA + 0xa0)).api('TlsFree').checkEax(1);
  // The initializing thread can exit while its static-TLS DLL remains rooted.
  // Another thread later unloads it: owned template storage/index are released
  // without treating the overwritten guest slot as an allocation to free.
  a.push(0).push(0).push(0).push(BASE + 0x2d00).push(0).push(0).api('CreateThread').eaxTo(0xd4);
  a.push(5000).emit(0x50).api('WaitForSingleObject').checkEax(0);
  a.push(DATA + 0xe4).emit(0xff, 0x35, u32(DATA + 0xd4)).api('GetExitCodeThread').checkEax(1).checkMem(0xe4,77);
  a.checkMem(0xe0,0x11223344).checkMem(0xcc,1);
  a.api('TlsAlloc').eaxTo(0xe8);
  a.push(55).emit(0x50).api('TlsSetValue').checkEax(1);
  a.emit(0xff,0x35,u32(DATA+0xd8)).api('FreeLibrary').checkEax(1).checkMem(0xc0,2);
  a.emit(0xff,0x35,u32(DATA+0xe8)).api('TlsGetValue').checkEax(55);
  a.emit(0xff,0x35,u32(DATA+0xe8)).api('TlsFree').checkEax(1);
